import{_ as r,o as i,c as o,a2 as s}from"./chunks/framework.DiFhKIuW.js";const f=JSON.parse('{"title":"Referer策略","description":"","frontmatter":{},"headers":[],"relativePath":"Browser/referer.md","filePath":"Browser/referer.md","lastUpdated":1702947580000}'),a={name:"Browser/referer.md"};function d(c,e,l,t,n,p){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="referer策略" tabindex="-1">Referer策略 <a class="header-anchor" href="#referer策略" aria-label="Permalink to &quot;Referer策略&quot;">​</a></h1><p>浏览器在发起网络请求时携带的<code>Referer</code>头部用于标识请求发起的源页面地址。它主要有以下用途：</p><ul><li>来源追踪：服务器可以通过<code>Referer</code>头部了解用户从哪个页面链接跳转过来的，这对于分析网站流量来源很有帮助。</li><li>防盗链：网站可以检查<code>Referer</code>头部来确定请求是否由授权的来源发起，以防止其他网站盗用资源。</li><li>缓存优化：代理服务器或CDN可能会根据<code>Referer</code>头部决定是否提供缓存内容。</li><li>个性化内容：网站可能根据<code>Referer</code>提供定制化内容或推荐。</li></ul><p>但是，也存在隐私问题，因为<code>Referer</code>可能会泄露用户浏览信息。因此，有时会通过<code>HTTP</code>头部的<code>Referrer-Policy</code>来控制<code>Referer</code>头部的发送策略。</p><p><code>Referrer-Policy</code> 可以由前端或服务端设置。</p><h2 id="前端设置" tabindex="-1">前端设置 <a class="header-anchor" href="#前端设置" aria-label="Permalink to &quot;前端设置&quot;">​</a></h2><p>在HTML中，可以通过<code>&lt;meta&gt;</code>标签来指定：</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">meta</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;referrer&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;no-referrer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>关于<code>meta</code>标签中<code>name</code>为<code>referrer</code>时，<code>content</code>可以是以下几个值：</p><ul><li><code>no-referrer</code>：不发送referer头部。</li><li><code>origin</code>：发送referer头部，但只包含主域部分。</li><li><code>no-referrer-when-downgrade</code>：默认值，对于跨协议请求（例如从HTTPS网页到HTTP网页），不发送<code>referer</code>头部；对于同协议请求，发送<code>referer</code>头部，但只包含主域部分。</li><li><code>origin-when-cross-origin</code>：对于跨域请求，发送<code>referer</code>头部，但只包含主域部分；对于同域请求，发送完整URL路径作为<code>referer</code>。</li><li><code>unsafe-url</code>：发送完整URL路径作为<code>referer</code>，包括路径和查询参数。</li></ul><p>当你将<code>meta</code>标签的<code>content</code>设置为<code>unsafe-url</code>时，它会将<code>referer</code>设置为完整的URL路径，包括路径和查询参数。这可能会带来以下安全风险：</p><ul><li>隐私泄露：完整的URL路径可能包含敏感信息，例如会话标识、个人身份信息等。将完整URL路径作为<code>referer</code>可能会泄露这些敏感信息给第三方网站。</li><li>信息泄露：通过<code>referer</code>头部，网站所有者可以获得访问来源的信息，包括从哪个网页跳转过来。使用完整URL路径作为<code>referer</code>可能会泄露用户访问来源的信息。</li><li>跨站请求伪造（CSRF）：完整URL作为<code>referer</code>可能会增加跨站请求伪造攻击的风险，攻击者可以利用<code>referer</code>来伪装请求来源，从而进行恶意操作。</li></ul><p>请注意，虽然在某些情况下使用<code>unsafe-url</code>可以满足你的需求，但它可能会增加安全风险。在使用时，请确保评估并采取适当的安全措施来保护用户隐私和防止潜在的攻击。</p><h2 id="服务端设置" tabindex="-1">服务端设置 <a class="header-anchor" href="#服务端设置" aria-label="Permalink to &quot;服务端设置&quot;">​</a></h2><p>在HTTP响应头中设置<code>Referrer-Policy</code>：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Referrer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: no</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">referrer</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>当服务端在响应中设置<code>Referrer-Policy</code>时，它会影响浏览器在处理当前页面的后续请求时<code>Referer</code>头部的发送行为。也就是说，服务端设置的<code>Referrer-Policy</code>会影响当前页面加载后续资源或发起的其他请求的<code>Referer</code>传递策略。</p><p>在实际应用中，通常希望服务端预先设置好<code>Referrer-Policy</code>，这样浏览器在接收到第一次响应后，就能够按照这个策略处理所有后续请求。如果服务端在后续的响应中改变或重新设置<code>Referrer-Policy</code>，那么浏览器将按照最新的策略处理接下来的请求。</p>',18)])])}const k=r(a,[["render",d]]);export{f as __pageData,k as default};
